import java.util.*;

class Solution {
    public boolean isPrime(int n) {
        if (n < 2) return false;                 // 0 and 1 are not prime
        for (long d = 2; d * d <= n; d++) {      // divisors pair up around sqrt(n)
            if (n % d == 0) return false;
        }
        return true;
    }
}

